import {readFile,writeFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {fixtureAdapter} from './reader/query-fixture.mjs';
import {handlePublicQuery} from './reader/query-http.mjs';
import {agentPages} from './reader/agent-pages.mjs';
import {launch} from '/Users/jr/Dev/lex-mex-reader/reader/browser-check.mjs';
const fixture=JSON.parse(await readFile(new URL('./reader/fixtures/public-query-v1.json',import.meta.url),'utf8')),adapter=fixtureAdapter(fixture),base=`https://test/lex-mex/api/r/${fixture.release.id}/`;
const results=[];
for(const [name,path] of [['null cursor',`instruments?cursor=${Buffer.from('null').toString('base64url')}`],['normalizes empty',`search?q=${encodeURIComponent('\u0301')}`]]){const r=await handlePublicQuery(new Request(base+path),adapter);results.push({name,status:r.status,body:await r.json()});}
const sha=b=>createHash('sha256').update(b).digest('hex'),release='a'.repeat(64),source={official_url:'http://example.invalid/source.pdf',publisher:'synthetic',source_sha256:'b'.repeat(64),retrieved_at:'2026-10-24'},text='\námbito\r\nsegunda línea';
const p={id:'urn:test:article:1',label:'Artículo1',text,text_sha256:sha(text),text_path:'p.txt',markdown_path:'p.md',source,heading_context:{},temporal_status:'unknown'};
const doc={id:'urn:test',slug:'test',short_name:'TEST',official_title:'Synthetic',latest_reform_date:null,source,provisions:[p]},manifest={release_id:release,base_path:'/lex-mex/',instruments:[{id:doc.id,slug:'test',document_path:'mx/test/instrument.json'}]},content=new Map([[`releases/${release}/mx/test/instrument.json`,Buffer.from(JSON.stringify(doc))]]);
content.set(`releases/${release}/manifest.json`,Buffer.from('{}'));content.set(`releases/${release}/mx/test/p.txt`,Buffer.from(text));content.set(`releases/${release}/mx/test/p.md`,Buffer.from('Markdown'));
const pages=agentPages(manifest,content),html=[...pages.files].find(([path])=>path.endsWith('/'+sha(p.id)+'.html'))[1].toString();
const b=await launch();try{await b.page.send('Page.navigate',{url:'data:text/html;charset=utf-8,'+encodeURIComponent(html)});await b.page.until('Boolean(document.querySelector("pre"))');const seen=await b.page.eval('document.querySelector("pre").textContent');results.push({name:'HTML exact text',same:seen===text,original:JSON.stringify(text),seen:JSON.stringify(seen),advertised:sha(text),seen_sha256:sha(seen),http_source_accepted:html.includes('http://example.invalid/source.pdf')});}finally{await b.close();}
await writeFile('/tmp/public-query-review-probes.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results,null,2));
